#requires -Version 5.1
<#
.SYNOPSIS
  Erzeugt HTML Smuggling Detection Test-Suite v4.8.1-r1 (Tests 01-72).

.DESCRIPTION
  - 72 HTML-Testdateien
  - README
  - CSV/JSON Manifest
  - 4 Sandbox-Configprofile
  - automatische ZIP-Erstellung
  - Tests 71/72 pruefen Exact-Override-Semantik fuer sandbox_escalation.reasons
#>

[CmdletBinding()]
param(
    [string]$OutputRoot = (Join-Path $PSScriptRoot 'HTML_Smuggling_v4.8.1_Tests_01-72'),
    [switch]$Force
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
$SuiteVersion = '4.8.1-r1'
$ExpectedHtmlTests = 72
$ExpectedFiles = 79

if ([string]::IsNullOrWhiteSpace($OutputRoot)) { throw 'OutputRoot darf nicht leer sein.' }
$OutputRoot = [System.IO.Path]::GetFullPath($OutputRoot)
if (Test-Path -LiteralPath $OutputRoot) {
  if (-not $Force) { throw "Zielordner existiert bereits: $OutputRoot. Mit -Force neu erstellen." }
  Remove-Item -LiteralPath $OutputRoot -Recurse -Force
}
New-Item -ItemType Directory -Path $OutputRoot -Force | Out-Null

function Write-EmbeddedFile {
  param([Parameter(Mandatory=$true)][string]$Name,[Parameter(Mandatory=$true)][string]$Base64)
  [System.IO.File]::WriteAllBytes(
    (Join-Path $OutputRoot $Name),
    [Convert]::FromBase64String(($Base64 -replace '\s',''))
  )
}

