foreach ($item in $EmbeddedFiles) {
  Write-EmbeddedFile -Name $item.Name -Base64 $item.Base64
}

$htmlFiles = @(Get-ChildItem -LiteralPath $OutputRoot -Filter 'test*.html' -File)
$allFiles = @(Get-ChildItem -LiteralPath $OutputRoot -File)

if ($htmlFiles.Count -ne $ExpectedHtmlTests) {
  throw "Erwartet $ExpectedHtmlTests HTML-Tests, gefunden $($htmlFiles.Count)."
}
if ($allFiles.Count -ne $ExpectedFiles) {
  throw "Erwartet $ExpectedFiles Dateien, gefunden $($allFiles.Count)."
}

$numbers = @()
foreach ($f in $htmlFiles) {
  if ($f.Name -match '^test(\d{2})_') { $numbers += [int]$Matches[1] }
}
$missing = @(1..72 | Where-Object { $_ -notin $numbers })
if ($missing.Count -gt 0) { throw "Fehlende Testnummern: $($missing -join ', ')" }

$zipPath = "$OutputRoot.zip"
if (Test-Path -LiteralPath $zipPath) { Remove-Item -LiteralPath $zipPath -Force }
Compress-Archive -Path (Join-Path $OutputRoot '*') -DestinationPath $zipPath -CompressionLevel Optimal

Write-Host ""
Write-Host "Suite erfolgreich erstellt: $SuiteVersion"
Write-Host "HTML-Tests : $($htmlFiles.Count)"
Write-Host "Default    : Tests 01-70"
Write-Host "Override   : Tests 71-72 mit sandbox_escalation_override_crypto.conf.example"
Write-Host "ZIP        : $zipPath"
